    lines = [f'# 文件：{path.name}', f'- 类型：PPTX', f'- 幻灯片数：{len(prs.slides)}', '']
    for idx, slide in enumerate(prs.slides, start=1):
        texts=[]
        for shape in slide.shapes:
            t=shape_text(shape)
