        combined='\n'.join(texts).strip()
        lines.append(f'## Slide {idx}')
        lines.append(combined if combined else '[未抽取到文字]')
        lines.append('')
    return '\n'.join(lines)

def extract_pdf(path):
    lines=[f'# 文件：{path.name}', f'- 类型：PDF', '']
    with pdfplumber.open(str(path)) as pdf:
