from pathlib import Path
import re, os
from pptx import Presentation
import pdfplumber

root = Path.cwd()
all_candidates = [p for p in root.rglob('*') if p.is_file() and p.suffix.lower() in {'.pptx', '.pdf'}]
# Keep the files under the user requirements folder by choosing the three newest/known project docs around this workspace, excluding hidden/cache/vendor.
files = []
for p in all_candidates:
    parts_lower = [part.lower() for part in p.parts]
    if '.git' in parts_lower or 'vendor' in parts_lower or '.playwright-mcp' in parts_lower or '.reasonix' in parts_lower:
        continue
    files.append(p)
files = sorted(files, key=lambda p: (p.suffix.lower(), str(p)))

out = Path(os.environ.get('TEMP', '.')) / 'hai_xiaonan_requirements_extract.md'

def clean_text(s):
    return re.sub(r'\n{3,}', '\n\n', s.replace('\r\n', '\n')).strip()

def shape_text(shape):
    parts = []
    if hasattr(shape, 'text') and shape.text:
        parts.append(shape.text)
    if getattr(shape, 'has_table', False):
        try:
            for row in shape.table.rows:
                cells = []
                for cell in row.cells:
                    txt = clean_text(cell.text)
                    if txt:
                        cells.append(txt)
                if cells:
                    parts.append(' | '.join(cells))
        except Exception:
            pass
    if getattr(shape, 'has_group_shape', False):
        for sub in shape.shapes:
            txt = shape_text(sub)
            if txt:
                parts.append(txt)
    return clean_text('\n'.join(parts))

def extract_pptx(path):
    prs = Presentation(str(path))
    lines = [f'# File: {path.name}', f'- Type: PPTX', f'- Slides: {len(prs.slides)}', '']
    for idx, slide in enumerate(prs.slides, start=1):
        texts=[]
        for shape in slide.shapes:
            t=shape_text(shape)
            if t:
                texts.append(t)
        try:
            notes = clean_text(slide.notes_slide.notes_text_frame.text)
            if notes:
                texts.append('Notes:\n' + notes)
        except Exception:
            pass
        combined=clean_text('\n'.join(texts))
        lines.append(f'## Slide {idx}')
        lines.append(combined if combined else '[No text extracted]')
        lines.append('')
    return '\n'.join(lines)

def extract_pdf(path):
    lines=[f'# File: {path.name}', f'- Type: PDF', '']
    with pdfplumber.open(str(path)) as pdf:
        lines.insert(2, f'- Pages: {len(pdf.pages)}')
        for idx, page in enumerate(pdf.pages, start=1):
            text = page.extract_text(x_tolerance=1, y_tolerance=3) or ''
            lines.append(f'## Page {idx}')
            lines.append(clean_text(text) if clean_text(text) else '[No text extracted]')
            lines.append('')
    return '\n'.join(lines)

all_text=[]
for f in files:
    try:
        if f.suffix.lower()=='.pptx':
            all_text.append(extract_pptx(f))
        elif f.suffix.lower()=='.pdf':
            all_text.append(extract_pdf(f))
    except Exception as e:
        all_text.append(f'# File: {f.name}\n[Extract failed] {type(e).__name__}: {e}\n')

text='\n\n---\n\n'.join(all_text)
out.write_text(text, encoding='utf-8')
print(str(out))
print('files', len(files))
for f in files:
    print(f.name, f.stat().st_size)
print('chars', len(text))
