  baseUrl: "/model-api/member1/deepseek-v4-flash-284b/v1/chat/completions",

  modelName: "DeepSeek-V4-Flash",

  apiKey: "d1e9bb89482ff32a8d7d2a71df97b9032aa4c5858df9ea57781029d05c03e15e",

  temperature: 0.35,

  maxTokens: 2048

};



export function aiChatRequestStream(promptText, onUpdate, onFinish, onError) {

  fetch(AiGlobalConfig.baseUrl, {

    method: "POST",

    headers: {

      "Content-Type": "application/json;charset=UTF-8",

      "Authorization": AiGlobalConfig.apiKey ? `Bearer ${AiGlobalConfig.apiKey}` : ""

    },

    body: JSON.stringify({

      model: AiGlobalConfig.modelName,

      messages: [{ role: "user", content: promptText }],

      temperature: AiGlobalConfig.temperature,

      max_tokens: AiGlobalConfig.maxTokens,

      stream: true

    })

  }).then(response => {

    if (!response.ok) throw new Error(`接口请求异常：${response.status} ${response.statusText}`);



    const reader = response.body.getReader();

    const decoder = new TextDecoder();

    let buffer = '';

    let fullContent = '';



    function read() {

      reader.read().then(({ done, value }) => {

        if (done) {

          if (onFinish) onFinish(fullContent);

          return;

        }



        buffer += decoder.decode(value, { stream: true });

        const lines = buffer.split('\n');

        buffer = lines.pop() || '';



        for (const line of lines) {

          if (line.startsWith('data: ')) {

            const data = line.slice(6).trim();

            if (data === '[DONE]') {

              if (onFinish) onFinish(fullContent);

              return;

            }

            try {

              const parsed = JSON.parse(data);

              const content = parsed.choices && parsed.choices[0] && parsed.choices[0].delta && parsed.choices[0].delta.content;

              if (content) {

                fullContent += content;

                onUpdate(fullContent);

              }

            } catch (e) {

              // ignore parse errors

            }

          }

        }

        read();

      });

    }

    read();

  }).catch(e => {

    if (onError) onError(e.message);

